import vm from'node:vm';import fs from'node:fs';import path from'node:path';import assert from'node:assert/strict';import{execFileSync}from'node:child_process';import{createHash}from'node:crypto';
const root=process.cwd(),out=path.resolve(process.argv[2]||'.ci-results/protected-pages'),head=execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),tracked=execFileSync('git',['ls-files','-z'],{encoding:'utf8'}).split('\0').filter(Boolean),core=['index.html','weather_today.json','weather_week.json','weather_rules.json','tide_today.json','tide_month.json','notices.json','birdmap-user-guide.png'];
const html=fs.readFileSync('index.html','utf8');for(const token of ['function publicationHead(fresh)','function contributorsCurrent()','_publicationStartedMono','data-publication-app','function publicationForgetLayer(layer,map)','performance.now()-publicationState.checkedMono<PUBLICATION_MAX_AGE',"publicationInvalidate(document.hidden?'hidden':'expired')","querySelectorAll('[data-publication-entry]')"])assert.ok(html.includes(token),'protective baseline requires '+token);assert.ok(!html.includes('/field-updates')&&!html.includes('id="fieldPanel"'),'standby must preserve field retirement');assert.equal(fs.existsSync(out),false,'Output must be new to avoid packaging old assets');fs.mkdirSync(out,{recursive:true});
const ctx=vm.createContext({});vm.runInContext(html.match(/var siteData=([^\n]+);/)[0]+'\n'+html.match(/siteData=siteData\.concat\([\s\S]*?\);/)[0],ctx);const sites=JSON.parse(JSON.stringify(ctx.siteData));assert.equal(sites.length,202);assert.equal(new Set(sites.map(x=>x.id )).size,202);const coordinateHash=createHash('sha256').update(JSON.stringify(sites.map(x=>[x.id,x.lat,x.lon]))).digest('hex');
const selected=tracked.filter(f=>core.includes(f)||/^(share|sites|site|images|assets|css|js)\//.test(f));for(const f of core)assert.ok(selected.includes(f),'missing required runtime asset '+f);const sha=b=>createHash('sha256').update(b).digest('hex'),files={};for(const f of selected){const dest=path.resolve(out,f);assert.ok(dest.startsWith(out+path.sep));fs.mkdirSync(path.dirname(dest),{recursive:true});const b=fs.readFileSync(f);fs.writeFileSync(dest,b);files[f]=sha(b);}fs.writeFileSync(path.join(out,'protected-baseline.json'),JSON.stringify({head,siteDataCount:sites.length,coordinatesSha256:coordinateHash,role:'standby protective Pages artifact, not a deployment',files},null,2)+'\n');console.log(JSON.stringify({head,files:selected.length,indexSha256:files['index.html'],out}));
